HECK_DISTANCE, raycastParams) if result then return result end end return nil end UserInputService.JumpRequest:Connect(function() if not wallhopEnabled or not humanoid or not rootPart then return end if os.clock() - lastHopTime < HOP_COOLDOWN then return end if humanoid.FloorMaterial == Enum.Material.Air then local wallHit = checkWall() if wallHit then lastHopTime = os.clock() local wallNormal = wallHit.Normal rootPart.CFrame = CFrame.lookAt(rootPart.Position, rootPart.Position + wallNormal) local jumpSpeed = humanoid.UseJumpPower and humanoid.JumpPower or math.sqrt(2 * workspace.Gravity * humanoid.JumpHeight) rootPart.AssemblyLinearVelocity = Vector3.new(rootPart.AssemblyLinearVelocity.X, jumpSpeed, rootPart.AssemblyLinearVelocity.Z) humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end end end)
